DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.staff_run_supervision()'::regprocedure) INTO d; d:=replace(d,$old$a.details->'new'->>'status'='cancelled' OR a.details->>'status'='cancelled'$old$,$new$a.details->'status'->>'to'='cancelled' OR a.details->>'status'='cancelled'$new$); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.staff_case_candidates(_case uuid) RETURNS TABLE(user_id uuid,full_name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c staff_cases; BEGIN SELECT * INTO c FROM staff_cases WHERE id=_case; IF NOT FOUND OR NOT staff_case_allowed(c.city_id,c.department) THEN RAISE EXCEPTION 'Case scope denied'; END IF; RETURN QUERY SELECT DISTINCT u.user_id,p.full_name FROM user_roles u LEFT JOIN profiles p ON p.id=u.user_id WHERE staff_case_member_allowed(u.user_id,c.city_id,c.department); END $$;
CREATE OR REPLACE FUNCTION public.staff_weekly_trends() RETURNS TABLE(week_start date,region text,city_id uuid,department text,resolved bigint,on_time bigint,reopened bigint,blocked bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (has_permission(auth.uid(),'team') OR has_permission(auth.uid(),'audit')) THEN RAISE EXCEPTION 'Supervisor permission required'; END IF; RETURN QUERY SELECT date_trunc('week',c.created_at AT TIME ZONE 'Asia/Karachi')::date,coalesce(s.region,'غیر مقرر'),c.city_id,c.department,count(*) FILTER(WHERE c.status='resolved'),count(*) FILTER(WHERE c.status='resolved' AND c.resolved_at<=c.due_at),sum(c.reopen_count)::bigint,count(*) FILTER(WHERE c.status='blocked') FROM staff_cases c LEFT JOIN staff_controls s ON s.user_id=c.assignee_id WHERE c.created_at>now()-interval '12 weeks' AND staff_case_allowed(c.city_id,c.department) GROUP BY 1,2,3,4 ORDER BY 1 DESC,2,3,4; END $$;
REVOKE ALL ON FUNCTION public.staff_case_candidates(uuid),public.staff_weekly_trends() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_case_candidates(uuid),public.staff_weekly_trends() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.staff_guard_quality_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c staff_cases; BEGIN
 SELECT * INTO c FROM staff_cases WHERE id=NEW.case_id;
 IF NEW.outcome<>'appeal' AND c.status NOT IN ('review','resolved') THEN RAISE EXCEPTION 'Review requires completed result'; END IF;
 IF NEW.outcome='appeal' AND NOT EXISTS(SELECT 1 FROM staff_quality_reviews r WHERE r.case_id=NEW.case_id AND r.member_id=NEW.member_id AND r.outcome<>'appeal') THEN RAISE EXCEPTION 'Existing independent review required before appeal'; END IF;
 PERFORM notify_user(NEW.member_id,'staff_quality','کام کے معیار کا جائزہ',CASE WHEN NEW.outcome='investigate' THEN 'آزاد تحقیق درکار ہے؛ جرم ثابت نہیں' ELSE 'جائزہ اور وضاحت آج کے کام میں دیکھیں' END,'/admin'); RETURN NEW; END $$;
CREATE TRIGGER staff_quality_result_guard BEFORE INSERT ON public.staff_quality_reviews FOR EACH ROW EXECUTE FUNCTION public.staff_guard_quality_review();
REVOKE ALL ON FUNCTION public.staff_guard_quality_review() FROM PUBLIC,anon,authenticated;